 useEffect(()=>{if(arrangeMode!=='step')return;const options=document.querySelector('.pattern-options');if(!options)return;const label=document.createElement('span'),group=document.createElement('div');label.className='orientation-label';label.textContent='ORIENTATION';group.className='orientation-options';for(const angle of[0,90,180,270]){const button=document.createElement('button');button.type='button';button.textContent=`${angle}°`;button.className=repeatAngle===angle?'active':'';button.setAttribute('aria-label',`Orientation ${angle}°`);button.setAttribute('aria-pressed',String(repeatAngle===angle));button.addEventListener('click',()=>setRepeatAngle(angle));group.append(button)}options.append(label,group);return()=>{label.remove();group.remove()}},[arrangeMode,repeatPattern,repeatAngle,rotation,unit,gap]);
 useEffect(()=>{const group=document.querySelector('.margin-controls'),tools=group?.querySelector('.margin-tools');if(!tools)return;const button=document.createElement('button');button.className=`guide-toggle ${showGuides?'active':''}`;button.setAttribute('aria-pressed',String(showGuides));button.textContent=showGuides?'Guides on':'Guides off';button.addEventListener('click',()=>setShowGuides(value=>!value));tools.prepend(button);return()=>button.remove()},[showGuides,margins,unit,preset,printer]);
 useEffect(()=>{const bed=document.querySelector('.bed');if(!bed)return;bed.querySelectorAll('.sheet-guide').forEach(node=>node.remove());if(!showGuides)return;const add=(className,label,inset)=>{const guide=document.createElement('div');guide.className=`sheet-guide ${className}`;guide.setAttribute('aria-label',label);Object.assign(guide.style,{left:`${inset.left/sheet.w*100}%`,right:`${inset.right/sheet.w*100}%`,top:`${inset.top/sheet.h*100}%`,bottom:`${inset.bottom/sheet.h*100}%`});const tag=document.createElement('span');tag.textContent=label;guide.append(tag);bed.append(guide)};add('margin-guide','CUT CONTOUR MARGIN',previewSide==='back'?{...margins,left:margins.right,right:margins.left}:margins);return()=>bed.querySelectorAll('.sheet-guide').forEach(node=>node.remove())},[showGuides,margins,sheet,art,nested,outputPreview,previewSide]);
 useEffect(()=>{const host=document.querySelector(printer===PRINTERS.epson.id?'.setup-artwork':'.left'),sampleButton=host?.querySelector('.sample');if(!host||!sampleButton||!art)return;const panel=document.createElement('section'),font=fontStatus(art);panel.className='duplex-panel';const kind='page',Kind=selectionName(true),sourceLabel='PDF',pageOptions=Array.from({length:art.pageCount||1},(_,i)=>`<option value="${i+1}">${Kind} ${i+1}</option>`).join('');panel.innerHTML=`${art.pageCount>1?`<label>Front ${kind} <select aria-label="Front selection">${pageOptions}</select></label>`:''}${font?`<p class="font-status ${font.level}">${font.text}</p>`:''}<button class="duplex-mode ${duplex?'active':''}">${duplex?'Both sides on':'Add back side'}</button>${duplex?`<div class="back-card"><input class="back-file" type="file" accept=".pdf"><div class="back-summary"><i>B</i><div><b>${backArt?.name||'Back side required'}</b><small>${backArt?`${selectionName(true)} ${backArt.pageNumber} of ${backArt.pageCount}`:'Choose a page or another PDF'}</small></div></div>${art.pageCount>1?`<label>Use front ${sourceLabel} <select aria-label="Back selection"><option value="">Select ${kind}</option>${pageOptions}</select></label>`:''}<button class="choose-back">Choose another file</button><p class="duplex-status ${!backArt?'pending':duplexMatch?'match':'mismatch'}">${!backArt?'Waiting for Back side':duplexMatch?'Reflected Cut Lines match':'Back rejected · reflected Cut Line does not match Front'}</p></div>`:''}`;const frontSelect=panel.querySelector('[aria-label="Front selection"]');if(frontSelect){frontSelect.value=art.pageNumber||1;frontSelect.addEventListener('change',event=>add([art.sourceFile],'front',+event.target.value))}panel.querySelector('.duplex-mode').addEventListener('click',()=>{const next=!duplex;setDuplex(next);if(next&&!backArt&&art.sourceFile&&art.pageCount>1)add([art.sourceFile],'back',Math.min(2,art.pageCount))});const backSelect=panel.querySelector('[aria-label="Back selection"]');if(backSelect){if(backArt?.sourceFile===art.sourceFile)backSelect.value=backArt.pageNumber;backSelect.addEventListener('change',event=>{if(event.target.value)add([art.sourceFile],'back',+event.target.value)})}const backInput=panel.querySelector('.back-file');backInput?.addEventListener('change',event=>add(event.target.files,'back'));panel.querySelector('.choose-back')?.addEventListener('click',()=>backInput?.click());host.insertBefore(panel,sampleButton);return()=>panel.remove()},[art,backArt,duplex,duplexMatch,printer]);
